CREATE TABLE IF NOT EXISTS categorias(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS livros(id INTEGER PRIMARY KEY AUTOINCREMENT,titulo TEXT NOT NULL,autor TEXT,isbn TEXT,ano_publicacao INTEGER,editora TEXT,assunto TEXT,categoria_id INTEGER,capa TEXT,ativo INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(categoria_id) REFERENCES categorias(id));
CREATE TABLE IF NOT EXISTS turmas(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL UNIQUE,serie TEXT,turno TEXT,ano_letivo INTEGER,ativo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS locais(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL UNIQUE,ativo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS exemplares(id INTEGER PRIMARY KEY AUTOINCREMENT,livro_id INTEGER NOT NULL,codigo_interno TEXT UNIQUE,localizacao TEXT,situacao TEXT NOT NULL DEFAULT 'No acervo',estado TEXT NOT NULL DEFAULT 'disponivel',turma_uso TEXT,data_retirada TEXT,turma_reserva TEXT,data_reserva TEXT,motivo_baixa TEXT,turma_id INTEGER,reserva_turma_id INTEGER,local_id INTEGER,data_prevista TEXT,uso_id INTEGER,FOREIGN KEY(livro_id) REFERENCES livros(id),FOREIGN KEY(turma_id) REFERENCES turmas(id),FOREIGN KEY(reserva_turma_id) REFERENCES turmas(id),FOREIGN KEY(local_id) REFERENCES locais(id));
CREATE TABLE IF NOT EXISTS circulacoes(id INTEGER PRIMARY KEY AUTOINCREMENT,exemplar_id INTEGER NOT NULL,livro_id INTEGER NOT NULL,turma_id INTEGER NOT NULL,codigo TEXT NOT NULL,titulo TEXT NOT NULL,autor TEXT,turma TEXT NOT NULL,serie TEXT,turno TEXT,ano_letivo INTEGER,retirada TEXT,prevista TEXT,devolucao TEXT,lote TEXT,migrado INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(exemplar_id) REFERENCES exemplares(id),FOREIGN KEY(livro_id) REFERENCES livros(id),FOREIGN KEY(turma_id) REFERENCES turmas(id));
CREATE TABLE IF NOT EXISTS inventarios(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,inicio TEXT NOT NULL,encerramento TEXT,local_id INTEGER,FOREIGN KEY(local_id) REFERENCES locais(id));
CREATE TABLE IF NOT EXISTS inventario_itens(id INTEGER PRIMARY KEY AUTOINCREMENT,inventario_id INTEGER NOT NULL,exemplar_id INTEGER NOT NULL,codigo TEXT,titulo TEXT,local_original TEXT,estado_original TEXT,conferido_em TEXT,local_observado TEXT,UNIQUE(inventario_id,exemplar_id),FOREIGN KEY(inventario_id) REFERENCES inventarios(id),FOREIGN KEY(exemplar_id) REFERENCES exemplares(id));
CREATE TABLE IF NOT EXISTS configuracao(chave TEXT PRIMARY KEY,valor TEXT NOT NULL);
